{% set company = frappe.get_doc("Company", doc.company) %}

{# Company Address #}
{% set address_links = frappe.get_all(
"Dynamic Link",
filters={
"link_doctype": "Company",
"link_name": company.name,
"parenttype": "Address"
},
fields=["parent"],
limit=1
) %}

{% if address_links %}
{% set addr = frappe.get_doc("Address", address_links[0].parent) %}
{% endif %}

{# Company Contacts #}
{% set contact_links = frappe.get_all(
"Dynamic Link",
filters={
"link_doctype": "Company",
"link_name": company.name,
"parenttype": "Contact"
},
fields=["parent"]
) %}

{% set phones = [] %}
{% set emails = [] %}

{% for link in contact_links %}
{% set contact = frappe.get_doc("Contact", link.parent) %}

{# Contact Numbers #}
{% for phone in contact.phone_nos %}
{% if phone.phone %}
{% if phones.append(phone.phone) %}{% endif %}
{% endif %}
{% endfor %}

{# Email IDs #}
{% for email in contact.email_ids %}
{% if email.email_id %}
{% if emails.append(email.email_id) %}{% endif %}
{% endif %}
{% endfor %}
{% endfor %}

{# Fallback to Company master if no Contact exists #}
{% if not phones and company.phone_no %}
{% if phones.append(company.phone_no) %}{% endif %}
{% endif %}

{% if not emails and company.email %}
{% if emails.append(company.email) %}{% endif %}
{% endif %}

<table class="border" style="width:100%; border-collapse:collapse; margin-top:10px">
    <tr>
        <td style="padding:0;">

            {% if company.company_logo %}
            <img src="{{ company.company_logo }}" style="width:100%; height:100px;">
            {% endif %}

            <div class="center" style="line-height:1.2; margin:2px 0;">
                <div style="font-weight:bold; font-style:italic;">
                    (Largest Manufacturer & Exporter in India)
                </div>

                <div>
                    National Awarded Company For The Best Exporter In Engineering Industries
                </div>
            </div>

            <div class="center" style="line-height:1.2;">

                {% if addr %}
                <div>
                    {{ addr.address_line1 }},
                    {% if addr.address_line2 %}
                    {{ addr.address_line2 }},
                    {% endif %}
                    {{ addr.city }}, {{ addr.state }}, {{ addr.pincode }}, {{ addr.country }}
                </div>
                {% endif %}

                {% if phones %}
                <div>
                    Phone: {{ phones | unique | join(" / ") }}
                </div>
                {% endif %}

                {% if emails or company.website %}
                <div>
                    {% if emails %}
                    Email: {{ emails | unique | join(" / ") }}
                    {% endif %}
                    {% if emails and company.website %} | {% endif %}
                    {% if company.website %}
                    W: {{ company.website }}
                    {% endif %}
                </div>
                {% endif %}

                {% if company.gstin %}
                <div>
                    GSTIN: {{ company.gstin }}
                </div>
                {% endif %}

            </div>
        </td>
    </tr>

    

</table>

<div style="
    width:100%;
    background:#fff200;
    border:1px solid #000;
    padding:8px;
    text-align:center;
    box-sizing:border-box;
    margin-top:-1px;
">
    <span >
       <b> {{doc.select_print_heading}}</b> <br>
        <b>No. {{ doc.name }}</b>
        &nbsp;&nbsp;&nbsp;
        <b>Dated: {{ frappe.utils.formatdate(doc.transaction_date) }}</b>
    </span>

</div>
